const fresh={removed:[],draft:[],editing:false,combo:false,drink:'',drinkError:false,qty:1};
export const initial={screen:'cardapio',category:'hamburgueres',product:'whopper',...fresh,picks:Object.fromEntries(Object.entries(categories).map(([k,c])=>[k,{product:c.products[0].id,qty:1}])),cart:[],lastRemoved:null,identification:idStart,customer:null,addressPick:null,delivery:null,addressPage:'lista',addressQuery:'',locateError:false,addressPlace:null,addressDraft:null,addressErrors:{}};
/** Selected product and Quantidade of the current photo category; null on Hambúrgueres. */
export const pick=s=>s.picks[s.category]??null;
const setPick=(s,v)=>({...s,picks:{...s.picks,[s.category]:{...pick(s),...v}}});
/** Same Item: product, Personalização, combo and drink; it then adds to the quantity already in the cart. */
