const digits=(v,n)=>String(v).replace(/\D/g,'').slice(0,n);
/** Errors of the Novo cliente's form: the name is required; the e-mail, optional, must look like one when filled. */
export const registerErrors=(name,email)=>({...(!name.trim()&&{name:'Informe seu nome completo.'}),...(email.trim()&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())&&{email:'Informe um e-mail válido.'})});
/** Identificação: celular typed, code sent, resent or switched channel, code typed and confirmed, Alterar celular, and the Novo cliente's form. */
