/** The Endereço salvo with this id, or null. */
export const savedAddress=(s,id)=>s.customer?.addresses.find(x=>x.id===id)??null;
/** Seus endereços: marking an Endereço salvo, and "Entregar neste endereço" with the one marked. */
/** Errors of the Dados de entrega: Rua, Bairro and Número (or "Endereço sem número") are required. */
export const deliveryErrors=d=>({...(!d.street.trim()&&{street:'Informe a rua.'}),...(!d.district.trim()&&{district:'Informe o bairro.'}),...(!d.noNumber&&!d.number.trim()&&{number:'Informe o número ou marque Endereço sem número.'})});
const choose=(s,place)=>place?{...s,addressPlace:{...place,pan:{x:0,y:0}},locateError:false,addressDraft:null,addressErrors:{}}:s;
/** Saving the Dados de entrega `d`: a new Endereço salvo ("Rua, Número" or "Rua, s/n"; the city of the place), marked in Seus endereços. */
function saveAddress(s,d){const errors=deliveryErrors(d);if(Object.keys(errors).length)return {...s,addressDraft:d,addressErrors:errors};const n=Math.max(0,...s.customer.addresses.map(x=>+(/^novo-(\d+)$/.exec(x.id)?.[1]??0)))+1,id=`novo-${n}`;const address={id,label:['Casa','Trabalho','Favoritos'].includes(d.label)?d.label:'Casa',street:`${d.street.trim()}, ${d.noNumber?'s/n':d.number.trim()}`,district:d.district.trim(),city:s.addressPlace.city,complement:d.noComplement?'':d.complement.trim(),reference:d.reference.trim()};return {...s,customer:{...s.customer,addresses:[...s.customer.addresses,address]},addressPick:id,addressPlace:null,addressQuery:'',addressDraft:null,addressErrors:{}}}
/** Seus endereços: marking an Endereço salvo, and "Entregar neste endereço" with the one marked. Novo endereço: the Busca, the location, the map and the Dados de entrega. */
function addressReducer(s,a){switch(a.type){case'addressPick':return savedAddress(s,a.id)?{...s,addressPick:a.id}:s;case'addressDeliver':return savedAddress(s,s.addressPick)?{...s,delivery:s.addressPick}:s;case'addressQuery':return {...s,addressQuery:String(a.value)};case'addressChoose':return choose(s,places.find(p=>p.id===a.id));case'addressLocated':return choose(s,locatedPlace);case'addressLocateFailed':return {...s,locateError:true};case'addressLocateReset':return {...s,locateError:false};case'addressPan':return s.addressPlace?{...s,addressPlace:{...s.addressPlace,pan:{x:a.x,y:a.y}}}:s;case'addressSave':return s.customer&&s.addressPlace?.served?saveAddress(s,a.draft):s;default:return s}}
export function reducer(s,a){if(a.type.startsWith('id'))return idReducer(s,a);if(a.type.startsWith('address'))return addressReducer(s,a);if(a.type==='continue')return continueCart(s);if(a.type.startsWith('item')){const n=itemReducer(s,a);return a.type==='itemRemove'||!n.lastRemoved?n:{...n,lastRemoved:null}}if(a.type==='category'&&a.category.startsWith('endereco/'))return {...reducer(s,{type:'category',category:'endereco'}),addressPage:a.category.slice(9)};if(a.type==='category')return ['carrinho','checkout','endereco'].includes(a.category)?{...s,screen:a.category,addressPage:'lista',locateError:false,lastRemoved:a.category==='carrinho'?s.lastRemoved:null,...(a.category==='endereco'&&s.screen==='checkout'&&s.delivery&&{addressPick:s.delivery})}:{...s,screen:'cardapio',lastRemoved:null,category:categories[a.category]?a.category:'hamburgueres'};if(pick(s)&&['select','qty','add'].includes(a.type))return photoReducer(s,a);switch(a.type){case'select':return s.product===a.product||!recipes[a.product]?s:{...s,...fresh,product:a.product};case'open':return {...s,editing:true,draft:[...s.removed]};case'toggle':if(!s.editing||layer(recipes[s.product],a.id)?.locked)return s;return {...s,draft:s.draft.includes(a.id)?s.draft.filter(x=>x!==a.id):[...s.draft,a.id]};case'remove':return s.draft.includes(a.id)?s:reducer(s,{type:'toggle',id:a.id});case'reset':return {...s,draft:[]};case'apply':return {...s,editing:false,removed:[...s.draft]};case'cancel':return {...s,editing:false,draft:[]};case'combo':return {...s,combo:a.value,drink:a.value?s.drink:'',drinkError:false};case'qty':return {...s,qty:clampQty(a.value)};case'drink':return s.combo?{...s,drink:a.value,drinkError:false}:s;case'add':if(s.combo&&!s.drink)return {...s,drinkError:true};return {...s,...fresh,cart:addItem(s.cart,{product:s.product,removed:[...s.removed],combo:s.combo,drink:s.drink,qty:s.qty,price:price(s)})};default:return s}}
/** Product names with ® raised, as in the Figma. */
export const marks=text=>text.replace(/®/g,'<span class="mark">®</span>');
export const comboFee=1200,drinks=['Coca-Cola','Coca-Cola Zero','Sprite','Fanta Laranja','Natural One Laranja','Natural One Uva','Água de Copo'],money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),price=s=>recipes[s.product].price+(s.combo?comboFee:0);
/** Total do item of the card on screen: unit price × Quantidade. */
export const itemTotal=s=>{const p=pick(s);return p?products[p.product].price*p.qty:price(s)*s.qty};
/** Name of the product an Item holds, burger or photo-only. */
export const itemName=item=>(recipes[item.product]??products[item.product]).name;
/** Units in the cart: the sum of every Item's Quantidade (header counter and the Carrinho's subtitle). */
export const cartUnits=cart=>cart.reduce((n,i)=>n+i.qty,0);
/** Total dos itens: the sum of every Item's Total do item (unit price × Quantidade). */
export const cartTotal=cart=>cart.reduce((n,i)=>n+i.price*i.qty,0);
